extract_daily_layers <- function(nc_file, expected_variable="2m_temperature") { if(!requireNamespace("terra",quietly=TRUE)) stop("terra is required"); r <- terra::rast(nc_file, subds=expected_variable); if(terra::nlyr(r)<1) stop("No layers found for ",expected_variable); d <- terra::time(r); if(length(d)!=terra::nlyr(r)||any(is.na(d))) { if(requireNamespace("ncdf4",quietly=TRUE)) { nc <- ncdf4::nc_open(nc_file); on.exit(ncdf4::nc_close(nc),add=TRUE); tv <- nc$dim$time; if(!is.null(tv)) d <- as.POSIXct(ncdf4::ncvar_get(nc,tv),origin="1970-01-01",tz="UTC") } }; d <- as.Date(d); if(length(d)!=terra::nlyr(r)||anyNA(d)) stop("NetCDF must contain valid time metadata for every layer"); if(anyDuplicated(d)) stop("Duplicate dates in NetCDF: ",paste(d[duplicated(d)],collapse=", ")); list(raster=r, dates=d) }
standardize_daily_raster <- function(source, template, boundary=NULL, resampling_method="bilinear", mask_to_boundary=FALSE, mask_to_template=TRUE) { if(!requireNamespace("terra",quietly=TRUE)) stop("terra is required"); out <- terra::project(source,template,method=resampling_method); if(mask_to_template) out <- terra::mask(out,template); if(mask_to_boundary&&!is.null(boundary)) out <- terra::mask(out,terra::vect(boundary)); out }
process_downloaded_mintemp <- function(raw_files,daily_dir,template_path,bbox_path,config,overwrite_dates=NULL) { fs::dir_create(daily_dir,recurse=TRUE); template <- terra::rast(template_path); before <- template_fingerprint(template); boundary <- if(isTRUE(config$spatial$mask_to_boundary)) sf::st_read(bbox_path,quiet=TRUE) else NULL; written <- character(); for(f in raw_files) { x <- extract_daily_layers(f,config$cds$variable); r <- x$raster; if(config$processing$source_units=="K") r <- r-273.15; for(i in seq_along(x$dates)) { d <- x$dates[i]; if(!is.null(overwrite_dates)&&!(d %in% as.Date(overwrite_dates))) next; out <- file.path(daily_dir,format_daily_filename(config$project$output_prefix,d)); z <- standardize_daily_raster(r[[i]],template,boundary,config$processing$resampling_method,isTRUE(config$spatial$mask_to_boundary),isTRUE(config$spatial$mask_to_template)); vr <- validate_raster_against_template(z,template,c(config$validation$minimum_celsius,config$validation$maximum_celsius),TRUE); if(!vr$valid) stop("Daily output failed validation for ",d,": ",vr$message); tmp <- paste0(out,".tmp"); terra::writeRaster(z,tmp,overwrite=TRUE,wopt=list(datatype=config$processing$datatype,gdal=c("COMPRESS=DEFLATE","PREDICTOR=3","TILED=YES"),NAflag=config$processing$naflag)); if(file.exists(out)) unlink(out); file.rename(tmp,out); est <- file.path(daily_dir,format_daily_filename(config$project$output_prefix,d,TRUE)); if(file.exists(est)&&isTRUE(config$processing$delete_replaced_estimates)) unlink(est); written <- c(written,out) } }; if(!identical(before,template_fingerprint(template))) stop("Template fingerprint changed during processing"); written }
